```go
package main

import "fmt"

func main() {
    done := make(chan struct{})
    message := "not ready"

    go func() {
        message = "ready"
        done <- struct{}{}
    }()

    <-done
    fmt.Println(message)
}
```
The write occurs before the send, and the matching receive completes before the print. The output is always `ready`.

```go
package main

import (
    "context"
    "fmt"
)

func main() {
    ctx, cancel := context.WithCancel(context.Background())
    cancel()

    var result <-chan int
    select {
    case value := <-result:
        fmt.Println(value)
    case <-ctx.Done():
        fmt.Println(ctx.Err())
    }
}
```
The result channel is nil, so that case is disabled. Cancellation is already ready, and the output is `context canceled`.
